package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.jlinalg.singlecell.TfidfMarkers;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Native marker statistics from supplied complete axes and sparse expression. */
public final class TfidfMarkersCli {
    private TfidfMarkersCli() { }
    static final String SCOPE="Native TF-IDF marker ranking with hypergeometric upper tails and per-cluster BH. Supplied genes, cells and clusters remain literal. The SoupX quickMarkers top-N convention can return markers with q>=FDR. This component does not estimate or remove ambient RNA, infer clusters, reproduce unspecified P008 settings or establish biological marker validity.";
    static final String ACTION="Require exit 0 and result_admitted=true. Inspect WARNINGS.md, analysis-status.json, provenance.json and both complete statistics.tsv and selected markers.tsv. Declare the expression units, cutoff, N and FDR. Correct the named input, capacity or heap cause and retry NEW paths; preserve failed attempts. For ambiguous numerical cutoff boundaries or a historical environment, check the selected original SoupX runtime before interpretation.";
    private record Request(Path genes,Path cells,Path counts,Path out,String units,int topN,double fdr,double cut,long bytes,int genesMax,int cellsMax,int entriesMax,long pairs,long operations,long outputBytes) { }
    private record Table(Path original,NextflowFiles.Pin pin,List<String[]> rows) { }
    private static final class Output {
        final long maximum;long used;
        Output(long maximum){this.maximum=maximum;}
        void write(OutputStream out,String text)throws IOException {byte[] raw=text.getBytes(StandardCharsets.UTF_8);require(raw.length<=maximum-used,"Generated marker tables exceed maximum_output_table_bytes");out.write(raw);used+=raw.length;}
    }
    public static void main(String[] args){System.exit(run(args,System.out,System.err));}
    public static int run(String[] args,PrintStream output,PrintStream error){
        if(args.length==0||Arrays.equals(args,new String[]{"--help"})){emit(output,"TF-IDF markers (native Java)\njava -cp DEVELOPMENT.jar org.jlinalg.cli.TfidfMarkersCli --request request.json\n\nClosed JSON: schema_version=1, mode=MARKERS, genes, cells, counts, out (NEW), expression_units (literal label), expression_cutoff (finite >=0), top_n (positive integer or string ALL), fdr (0<FDR<=1). UTF-8 unquoted TSV: genes header gene_id; cells header cell_id,cluster; counts header gene_id,cell_id,value. Counts are nonnegative finite decimal sparse entries; absent coordinates are zero, duplicate coordinates are refused. Complete axes include zero genes/cells. Require at least two genes and observed groups with above-cutoff expression in each group. Optional maximum_input_bytes=134217728, maximum_genes=100000, maximum_cells=1000000, maximum_entries=1000000, maximum_gene_cluster_pairs=1000000, maximum_operations=100000000, maximum_output_table_bytes=1073741824. Paths resolve against the request.\n\n"+SCOPE+"\n\n"+ACTION);return 0;}
        try{
            var options=FollowupSupport.options(args,Set.of("request"));Path source=Path.of(FollowupSupport.required(options,"request")).toAbsolutePath().normalize();var sourcePin=NextflowFiles.pin(source,1<<20,()->{});byte[] raw=NextflowFiles.bytes(source,1<<20);require(raw.length==sourcePin.bytes()&&NextflowFiles.sha(raw).equals(sourcePin.sha256()),"Request changed during intake");Request r=parse(object(NextflowParameters.parse(NextflowFiles.utf8(raw),1<<20,100000)),source.getParent());int[] exit={0};
            FollowupSupport.transaction(Map.of("out",r.out.toString()),"native-tfidf-markers",(stage,manifest)->{
                var state=new LinkedHashMap<String,Object>();state.put("result_admitted",false);var warnings=new ArrayList<String>();warnings.add(SCOPE);
                warnings.add("METHOD REVIEW: expression is strictly value>expression_cutoff; no normalization or log transformation is performed. Gene/group order uses unsigned UTF-8 bytes (C collation). Groups are observed string labels, not unused R factor levels. Values outside the selected component domain are refused. Ordinary double tail/BH arithmetic can differ from a particular R build near an exact cutoff; no bitwise or biological equivalence is claimed.");
                try{
                    Path inputs=Files.createDirectory(stage.resolve("inputs"));Files.write(inputs.resolve("request.json"),raw,StandardOpenOption.CREATE_NEW);verify(source,sourcePin);
                    Table genes=capture(r.genes,inputs.resolve("genes.tsv"),r.bytes,r.genesMax,"gene_id");Table cells=capture(r.cells,inputs.resolve("cells.tsv"),r.bytes-genes.pin.bytes(),r.cellsMax,"cell_id\tcluster");Table counts=capture(r.counts,inputs.resolve("counts.tsv"),r.bytes-genes.pin.bytes()-cells.pin.bytes(),r.entriesMax,"gene_id\tcell_id\tvalue");
                    var geneNames=new ArrayList<String>();var cellNames=new ArrayList<String>();var clusters=new ArrayList<String>();var geneIndex=new HashMap<String,Integer>();var cellIndex=new HashMap<String,Integer>();
                    for(String[] row:genes.rows){require(geneIndex.putIfAbsent(row[0],geneNames.size())==null,"Duplicate literal gene ID");geneNames.add(row[0]);}
                    for(String[] row:cells.rows){require(cellIndex.putIfAbsent(row[0],cellNames.size())==null,"Duplicate literal cell ID");cellNames.add(row[0]);clusters.add(row[1]);}
                    var entries=new ArrayList<TfidfMarkers.Entry>();
                    for(String[] row:counts.rows){require(geneIndex.containsKey(row[0])&&cellIndex.containsKey(row[1]),"Sparse entry names an undeclared gene/cell; no intersection or identifier repair");require(row[2].matches("[+]?(?:[0-9]+(?:[.][0-9]*)?|[.][0-9]+)(?:[eE][+-]?[0-9]+)?"),"Require nonnegative complete finite decimal values; missing values are not omitted");double value=Double.parseDouble(row[2]);require(Double.isFinite(value),"Nonfinite sparse entry refused");entries.add(new TfidfMarkers.Entry(geneIndex.get(row[0]),cellIndex.get(row[1]),value));}
                    var budget=new TfidfMarkers.Budget(r.operations);var result=TfidfMarkers.calculate(geneNames,cellNames,clusters,entries,r.topN,r.fdr,r.cut,r.pairs,budget);Path results=Files.createDirectory(stage.resolve("results"));var written=new Output(r.outputBytes);
                    String header="gene_id\tcluster\texpressing_cells\tcluster_cells\tglobal_expressing_cells\tgene_frequency\toutside_frequency\tsecond_best_frequency\tglobal_frequency\tsecond_best_cluster\ttfidf\tidf\tp_value\tbh_q_value\tselected\n";
                    for(boolean selected:List.of(false,true))try(var writer=Files.newOutputStream(results.resolve(selected?"markers.tsv":"statistics.tsv"),StandardOpenOption.CREATE_NEW)){
                        written.write(writer,header);for(var v:selected?result.markers():result.statistics())written.write(writer,String.join("\t",v.gene(),v.cluster(),Integer.toString(v.expressingCells()),Integer.toString(v.clusterCells()),Integer.toString(v.globalExpressingCells()),token(v.frequency()),token(v.outsideFrequency()),token(v.secondBestFrequency()),token(v.globalFrequency()),v.secondBestCluster(),token(v.tfidf()),token(v.idf()),token(v.pValue()),token(v.qValue()),Boolean.toString(v.selected()))+"\n");
                    }
                    long nonfinite=result.statistics().stream().filter(v->!Double.isFinite(v.tfidf())||!Double.isFinite(v.idf())).count();long boundary=result.statistics().stream().filter(v->Math.abs(v.qValue()-r.fdr)<=Math.max(64*Math.ulp(r.fdr),3e-12*r.fdr)).count();
                    if(result.selectedOutsideFdr()>0)warnings.add("SELECTION WARNING: "+result.selectedOutsideFdr()+" selected markers have q>=FDR. This follows the source top-N branch; selection is not an assertion that every returned marker passes FDR.");
                    if(nonfinite>0)warnings.add("NUMERIC DIAGNOSTIC: "+nonfinite+" complete statistic rows contain original-formula Inf IDF/NaN TF-IDF for genes with no above-cutoff expression. They are retained explicitly, not replaced with zero.");
                    if(boundary>0)warnings.add("CUTOFF REVIEW REQUIRED: "+boundary+" q values are within the reported numerical boundary band (max(64 ulps,3e-12 relative)) of FDR. Native strict comparisons use their computed values; a different R build may choose a different side. Recheck the original selected runtime when that decision matters.");
                    for(Table t:List.of(genes,cells,counts))verify(t.original,t.pin);verify(source,sourcePin);
                    var provenance=new LinkedHashMap<String,Object>();provenance.put("mode","MARKERS");provenance.put("expression_units",r.units);provenance.put("expression_cutoff",r.cut);provenance.put("top_n",r.topN<0?"ALL":r.topN);provenance.put("fdr",r.fdr);provenance.put("fdr_comparison","strict");provenance.put("adjustment","BH-per-cluster-complete-gene-family");provenance.put("ordering","unsigned-UTF8-C-collation");provenance.put("genes",geneNames.size());provenance.put("cells",cellNames.size());provenance.put("entries",entries.size());provenance.put("statistics",result.statistics().size());provenance.put("markers",result.markers().size());provenance.put("selected_outside_fdr",result.selectedOutsideFdr());provenance.put("nonfinite_statistic_rows",nonfinite);provenance.put("near_cutoff_rows",boundary);provenance.put("generated_table_bytes",written.used);provenance.put("operations",result.operations());provenance.put("input_sha256",Map.of("genes",genes.pin.sha256(),"cells",cells.pin.sha256(),"counts",counts.pin.sha256()));provenance.put("request_sha256",sourcePin.sha256());provenance.put("ambient_rna_estimated_or_removed",false);NextflowFiles.writeJson(stage.resolve("provenance.json"),provenance);
                    state.put("status","PASS_NATIVE_TFIDF_MARKERS");state.put("result_admitted",true);
                }catch(Exception failure){exit[0]=2;state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("cause",failure.toString());warnings.add("FAIL2: "+failure);quarantine(stage);}
                catch(OutOfMemoryError failure){exit[0]=2;state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("cause","Java heap exhausted");warnings.add("FAIL2: Java heap exhausted; choose a permitted heap/input size and retry NEW paths.");quarantine(stage);}
                state.put("required_action",ACTION);NextflowFiles.writeJson(stage.resolve("analysis-status.json"),state);Files.writeString(stage.resolve("WARNINGS.md"),"# "+state.get("status")+"\n\n"+String.join("\n\n",warnings)+"\n\nREQUIRED ACTION: "+ACTION+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);manifest.put("result_admitted",state.get("result_admitted"));manifest.put("scope",SCOPE);
            });emit(exit[0]==0?output:error,(exit[0]==0?"Native marker analysis admitted: ":"FAIL2 NO RESULT ADMITTED: ")+r.out);emit(error,"WARNINGS / REQUIRED ACTIONS: "+r.out.resolve("WARNINGS.md")+"\n"+ACTION);return exit[0];
        }catch(Exception failure){emit(error,"FAIL2 NO RESULT ADMITTED: "+failure+"\n"+ACTION);return 2;}
    }
    private static Request parse(Map<String,Object> m,Path parent)throws IOException{
        var allowed=Set.of("schema_version","mode","genes","cells","counts","out","expression_units","expression_cutoff","top_n","fdr","maximum_input_bytes","maximum_genes","maximum_cells","maximum_entries","maximum_gene_cluster_pairs","maximum_operations","maximum_output_table_bytes");for(String key:m.keySet())require(allowed.contains(key),"Unknown marker field: "+key);
        integer(m.get("schema_version"),1,1);require(text(m.get("mode")).equals("MARKERS"),"Declare MARKERS mode");int n="ALL".equals(m.get("top_n"))?-1:(int)integer(m.get("top_n"),1,10000000);double fdr=finite(m.get("fdr"),0,1);require(fdr>0,"Require FDR>0");
        return new Request(resolve(parent,label(m.get("genes"))),resolve(parent,label(m.get("cells"))),resolve(parent,label(m.get("counts"))),resolve(parent,label(m.get("out"))),label(m.get("expression_units")),n,fdr,finite(m.get("expression_cutoff"),0,Double.MAX_VALUE),number(m,"maximum_input_bytes",128L<<20,1,512L<<20),(int)number(m,"maximum_genes",100000,2,10000000),(int)number(m,"maximum_cells",1000000,2,10000000),(int)number(m,"maximum_entries",1000000,1,10000000),number(m,"maximum_gene_cluster_pairs",1000000,1,20000000),number(m,"maximum_operations",100000000,1,10000000000L),number(m,"maximum_output_table_bytes",1L<<30,1,128L<<30));
    }
    private static Table capture(Path original,Path copy,long capacity,int maximum,String header)throws IOException{
        require(capacity>=0,"Complete input byte capacity exceeded");var expected=NextflowFiles.pin(original,capacity,()->{});try(var in=Files.newInputStream(original,LinkOption.NOFOLLOW_LINKS);var out=Files.newOutputStream(copy,StandardOpenOption.CREATE_NEW)){byte[] buffer=new byte[65536];long count=0;for(int n=in.read(buffer);n>=0;n=in.read(buffer)){require(n<=capacity-count,"Input grew beyond byte capacity");out.write(buffer,0,n);count+=n;}require(count==expected.bytes(),"Input size changed during capture");}verify(copy,expected);verify(original,expected);
        String text=NextflowFiles.utf8(Files.readAllBytes(copy));require(!text.startsWith("\ufeff")&&text.indexOf('\0')<0,"Refuse BOM/NUL in literal TSV");String[] lines=text.split("\n",-1);int length=lines.length;if(lines[length-1].isEmpty())length--;require(length>=1,"Empty TSV");require(line(lines[0]).equals(header),"Require exact header: "+header);require(length-1<=maximum,"TSV exceeds declared row capacity");int width=header.split("\t",-1).length;var rows=new ArrayList<String[]>();
        for(int i=1;i<length;i++){String s=line(lines[i]);require(!s.isEmpty()&&s.indexOf('\r')<0,"Empty/bare-CR row refused");String[] row=s.split("\t",-1);require(row.length==width,"Unexpected TSV width");for(String token:row)require(!token.isEmpty(),"Empty TSV field refused");rows.add(row);}return new Table(original,expected,List.copyOf(rows));
    }
    private static String line(String s){return s.endsWith("\r")?s.substring(0,s.length()-1):s;}
    private static String token(double d){return d==Double.POSITIVE_INFINITY?"Inf":d==Double.NEGATIVE_INFINITY?"-Inf":Double.toString(d);}
    private static void verify(Path path,NextflowFiles.Pin expected)throws IOException{require(expected.equals(NextflowFiles.pin(path,expected.bytes(),()->{})),"Input/request changed during marker calculation");}
    private static void quarantine(Path stage)throws IOException{Path from=stage.resolve("results").toAbsolutePath().normalize(),to=stage.resolve("unadmitted-partial-results").toAbsolutePath().normalize();require(from.getParent().equals(stage.toAbsolutePath().normalize())&&to.getParent().equals(from.getParent()),"Unsafe result quarantine paths");if(Files.exists(from))Files.move(from,to);}
    private static void emit(PrintStream stream,String text){byte[] raw=(text+"\n").getBytes(StandardCharsets.UTF_8);stream.write(raw,0,raw.length);stream.flush();}
}
